//! 🧪️ The first actual Drawing original field inverse has exact native source, denial and cancellation receipts.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128}}
fn source<T:semio_framework_value::retirement::RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{RetainedCloneSource::admit_owned(value,(),grant()).unwrap_or_else(|_|panic!("original Drawing inverse source")).0}
#[test]
fn original_visible_inverse_receives_original_affected_value_and_closes_every_partial(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../✅️validation/🧪️.json")).unwrap();let factory=store::os_store::document_store_owners::BoundedArtifactRetirementFactory::<DrawingMutation>::new();let context=RetainedMutationCloseContext{mutations:&factory};let g=grant();
 for cut in [0,1,20,200,100000]{let snapshot:DrawingSnapshot=serde_json::from_value(corpus["base"].clone()).unwrap();let root=layer_base(snapshot.layers.get(0).unwrap());let expected=serde_json::json!([{"mutation":"setLayerVisible","layerId":root.id.to_string_owner(),"visible":root.visible}]);let mutation:DrawingMutation=serde_json::from_value(serde_json::json!({"mutation":"setLayerVisible","layerId":root.id.to_string_owner(),"visible":!root.visible})).unwrap();let mut before=source(snapshot);let mut authored=source(mutation);let mut owner=DrawingOriginalFieldInverse::default();
  for _ in 0..cut{let d=owner.demand(before.borrow(),authored.borrow(),g.maximum_copy_bytes).unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=0,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=0,3 if d.release_bytes>0=>denied.maximum_release_bytes=0,4 if d.depth>0=>denied.maximum_depth=0,_=>continue}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.advance(before.borrow(),authored.borrow(),g.maximum_copy_bytes,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((b,r),(0,0));assert_eq!(owner.demand(before.borrow(),authored.borrow(),g.maximum_copy_bytes).unwrap(),d);}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.advance(before.borrow(),authored.borrow(),g.maximum_copy_bytes,g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!((b,r),(p.retained_capacity_bytes,p.released_bytes));if owner.ready(){break}}
  if cut==100000{assert!(owner.ready())}if owner.ready(){let(rows,p)=owner.take(g).unwrap();assert!(p.fits(g));let rows=rows.unwrap();assert_eq!(serde_json::to_value(&rows).unwrap(),expected);let(mut close,_)=FactoryVectorRetirement::admit(rows,g).unwrap_or_else(|_|panic!("original inverse output issuer"));while !close.terminal_is_empty(){close.close_step(&factory,g).unwrap();}}
  owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.close_step(context,g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!((b,r),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());while !before.terminal_is_empty(){before.close_step(g).unwrap();}while !authored.terminal_is_empty(){authored.close_step(g).unwrap();}
 }
}
